app.all("/api/x402", async (c2) => {
  const price = 0.01;
  const resourceUrl = `${new URL(c2.req.url).origin}/api/x402`;
  const requirements = buildPaymentRequirements(
    c2.env,
    resourceUrl,
    "Synapse Lounge x402 access and service manifest",
    price
  );
  const resource = {
    url: resourceUrl,
    description: "Synapse Lounge x402 access and service manifest",
    mimeType: "application/json",
    serviceName: "Synapse Lounge",
    tags: ["x402", "mcp", "ai-agents", "games", "social"],
    iconUrl: `${new URL(c2.req.url).origin}/favicon.ico`
  };
  const paymentHeader = getPaymentHeader(c2.req.raw);
  if (!paymentHeader) {
    const paymentRequired = buildPaymentRequired(requirements, resource, "x402_access");
    const json2 = JSON.stringify(paymentRequired);
    return new Response(json2, {
      status: 402,
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": "no-store",
        "PAYMENT-REQUIRED": encodeBase64Utf8(json2)
      }
    });
  }
  let paymentPayload = null;
  try {
    paymentPayload = JSON.parse(decodeBase64Utf8(paymentHeader));
  } catch {
    return c2.json({ x402Version: 2, error: "invalid_payment", message: "PAYMENT-SIGNATURE header is not valid base64 JSON." }, 402);
  }
  if (!paymentPayload || paymentPayload.x402Version !== 2 || !paymentPayload.accepted || !paymentPayload.payload) {
    return c2.json({ x402Version: 2, error: "invalid_payment", message: "PAYMENT-SIGNATURE does not contain a valid x402 v2 payment payload." }, 402);
  }
  try {
    const runtimeCrypto = globalThis.crypto;
    console.log("CRYPTO DEBUG", {
      cryptoType: typeof runtimeCrypto,
      getRandomValuesType: typeof runtimeCrypto?.getRandomValues,
      randomUUIDType: typeof runtimeCrypto?.randomUUID
    });
    const cdpFacilitator = createCdpFacilitatorClient({
      apiKeyId: c2.env.CDP_API_KEY_ID,
      apiKeySecret: c2.env.CDP_API_KEY_SECRET
    });
    console.log("CDP DEBUG: client created");
    const verification = await cdpFacilitator.verify(
      paymentPayload,
      requirements
    );
    console.log("CDP DEBUG: verification completed", {
      isValid: verification.isValid,
      invalidReason: verification.invalidReason
    });
    if (!verification.isValid) {
      return c2.json({ x402Version: 2, error: "payment_verification_failed", message: verification.invalidReason || "Payment could not be verified." }, 402);
    }
    const settle2 = await cdpFacilitator.settle(
      paymentPayload,
      requirements
    );
    console.log("CDP DEBUG: settlement completed", {
      success: settle2.success,
      errorReason: settle2.errorReason,
      transaction: settle2.transaction
    });
    if (!settle2.success) {
      return c2.json({ x402Version: 2, error: "payment_settlement_failed", message: settle2.errorReason || "Payment could not be settled." }, 402);
    }
    const response = c2.json({
      service: "Synapse Lounge",
      version: "2.0.1",
      paid: true,
      price_usd: price,
      currency: "USDC",
      network: settle2.network || "eip155:8453",
      mcp: `${new URL(c2.req.url).origin}/mcp`,
      documentation: `${new URL(c2.req.url).origin}/for-agents`,
      message: "x402 access verified. Connect to the MCP endpoint for Synapse Lounge tools, games, social features, and paid experiences."
    });
    response.headers.set("Cache-Control", "no-store");
    if (settle2.transaction) {
      response.headers.set("PAYMENT-RESPONSE", encodeBase64Utf8(JSON.stringify({
        success: true,
        transaction: settle2.transaction,
        network: settle2.network || "eip155:8453",
        payer: settle2.payer || verification.payer
      })));
    }
    return response;
  } catch (error62) {
    console.error("X402 FULL ERROR:", error62);
    console.error(
      "X402 STACK:",
      error62 instanceof Error ? error62.stack : String(error62)
    );
    return c2.json(
      {
        error: "x402_internal_error",
        message: error62 instanceof Error ? error62.message : String(error62)
      },
      500
    );
  }
});
